    foreach($products as $i=>$p){$slug=strtolower(iconv('UTF-8','ASCII//TRANSLIT',$p[2]));$slug=preg_replace('/[^a-z0-9]+/','-',$slug);$slug=trim($slug,'-');$s=$pdo->prepare("INSERT INTO products(category_id,brand_id,name,slug,sku,barcode,short_description,description,purchase_price,sale_price,compare_price,vat_rate,stock,critical_stock,shipping_policy,same_day_delivery,is_active,is_featured,is_new,is_bestseller,sales_count,created_at,updated_at) VALUES(?,?,?,?,?,?,?, ?,?,?,?,?,?,5,?,1,1,1,1,1,?,NOW(),NOW()) ON DUPLICATE KEY UPDATE name=VALUES(name),category_id=VALUES(category_id),brand_id=VALUES(brand_id),sale_price=VALUES(sale_price),stock=VALUES(stock)");$s->execute([$p[0],$p[1],$p[2],$slug,$p[3],$p[4],'TOPLUCA demo ürünü. Yönetim panelinden tüm ürün bilgilerini, görselleri, stok ve fiyatları düzenleyebilirsiniz.','Profesyonel e-ticaret akışını göstermek için eklenmiş örnek üründür.',$p[5],$p[6],$p[7],20,$p[8],$p[9],20+$i*11]);}

    $pdo->exec("INSERT INTO product_price_tiers(product_id,min_qty,max_qty,unit_price,is_active) SELECT id,5,9,ROUND(sale_price*0.96,2),1 FROM products WHERE NOT EXISTS(SELECT 1 FROM product_price_tiers t WHERE t.product_id=products.id AND t.min_qty=5)");
    $pdo->exec("INSERT INTO product_price_tiers(product_id,min_qty,max_qty,unit_price,is_active) SELECT id,10,NULL,ROUND(sale_price*0.92,2),1 FROM products WHERE NOT EXISTS(SELECT 1 FROM product_price_tiers t WHERE t.product_id=products.id AND t.min_qty=10)");

    $pdo->exec("INSERT INTO shipping_companies(name,code,base_fee,free_shipping_limit,estimated_days,is_active,sort_order) VALUES('Yurtiçi Kargo','yurtici',89.90,750,'1-3 iş günü',1,1),('MNG Kargo','mng',84.90,750,'1-3 iş günü',1,2),('Aras Kargo','aras',87.90,750,'1-3 iş günü',1,3) ON DUPLICATE KEY UPDATE name=VALUES(name),base_fee=VALUES(base_fee)");
    $districts=['Çankaya','Yenimahalle','Keçiören','Mamak','Etimesgut','Sincan','Altındağ','Gölbaşı','Pursaklar'];$st=$pdo->prepare("INSERT INTO same_day_districts(district_name,is_active,sort_order) VALUES(?,1,?) ON DUPLICATE KEY UPDATE district_name=VALUES(district_name)");foreach($districts as $i=>$d){$st->execute([$d,$i+1]);}
