    $pdo->exec("INSERT INTO homepage_sections(section_type,title,subtitle,sort_order,is_active,created_at,updated_at) VALUES('hero','TOPLUCA','İhtiyacın olan ne varsa, Topluca.',1,1,NOW(),NOW()),('categories','Kategoriler','Ne arıyorsanız burada',2,1,NOW(),NOW()),('bestsellers','Çok Satanlar','En çok tercih edilen ürünler',3,1,NOW(),NOW()),('promo','Avantajlı Alışveriş','Toplu alımlarda daha avantajlı fiyatlar',4,1,NOW(),NOW()),('featured','Öne Çıkanlar','Sizin için seçtiklerimiz',5,1,NOW(),NOW()),('brands','Popüler Markalar','Güvendiğiniz markalar',6,1,NOW(),NOW())");
    $pdo->exec("INSERT INTO banners(title,subtitle,position_code,link_url,button_text,sort_order,is_active,created_at,updated_at) VALUES('Ofis ve okul ihtiyaçların TOPLUCA’da','Kırtasiye, kitap, teknoloji ve daha fazlası tek sepette.','home_hero','search.php','Alışverişe Başla',1,1,NOW(),NOW()),('Kitaplarda Avantajlı Fiyatlar','Sınav hazırlık ve yardımcı kaynaklar','home_mid_left','category.php?slug=kitap','Kitapları İncele',1,1,NOW(),NOW()),('Teknoloji Fırsatları','Bilgisayar bileşenleri ve aksesuarlar','home_mid_right','category.php?slug=bilgisayar-sarf-malzemeleri','Ürünleri İncele',1,1,NOW(),NOW())");
}

function drop_topluca_tables(PDO $pdo): void {
    $tables=['page_views','stock_movements','purchase_items','purchases','suppliers','search_synonyms','search_logs','campaigns','homepage_sections','banners','payments','order_status_history','order_items','orders','same_day_holidays','same_day_districts','shipping_companies','cart_items','carts','favorites','product_price_tiers','product_attributes','product_images','product_categories','products','brands','categories','user_addresses','users','login_attempts','admin_logs','admins','settings'];
    $pdo->exec('SET FOREIGN_KEY_CHECKS=0');foreach($tables as $t){$pdo->exec('DROP TABLE IF EXISTS `'.$t.'`');}$pdo->exec('SET FOREIGN_KEY_CHECKS=1');
}
